from dataclasses import dataclass

DEFAULT_TIMEOUT_SECONDS = 12


@dataclass(frozen=True)
class RequestOptions:
    timeout_seconds: int = DEFAULT_TIMEOUT_SECONDS
    retries: int = 2
    verify_tls: bool = True

    def validate(self):
        if self.timeout_seconds <= 0:
            raise ValueError("timeout must be positive")
        if self.retries < 0:
            raise ValueError("retries cannot be negative")
        return self


class RequestCounter:
    def __init__(self):
        self.successes = 0
        self.failures = 0

    def record(self, succeeded):
        if succeeded:
            self.successes += 1
        else:
            self.failures += 1

    def summary(self):
        total = self.successes + self.failures
        return {
            "total": total,
            "successes": self.successes,
            "failures": self.failures,
            "success_rate": self.successes / total if total else 0.0,
        }

const RETRY_LIMIT = 2;

export class WorkQueue {
  constructor() {
    this.pending = [];
    this.completed = [];
    this.failed = [];
  }

  enqueue(id, payload) {
    if (this.pending.some((item) => item.id === id)) {
      throw new Error("duplicate work id");
    }
    this.pending.push({ id, payload, attempts: 0 });
  }

  take() {
    return this.pending.shift() ?? null;
  }

  finish(item, result) {
    this.completed.push({ id: item.id, result });
  }

  retry(item) {
    const next = { ...item, attempts: item.attempts + 1 };
    if (next.attempts > RETRY_LIMIT) {
      this.failed.push(next);
      return false;
    }
    this.pending.push(next);
    return true;
  }

  counts() {
    return {
      pending: this.pending.length,
      completed: this.completed.length,
      failed: this.failed.length,
    };
  }
}

from collections import deque

MAX_RECENT_EVENTS = 24


class EventLedger:
    def __init__(self):
        self.recent = deque(maxlen=MAX_RECENT_EVENTS)
        self.totals = {}
        self.sequence = 0

    def append(self, kind, value):
        if not isinstance(kind, str) or not kind:
            raise ValueError("kind must be a nonempty string")
        self.sequence += 1
        event = {
            "sequence": self.sequence,
            "kind": kind,
            "value": value,
        }
        self.recent.append(event)
        self.totals[kind] = self.totals.get(kind, 0) + 1
        return event.copy()

    def since(self, sequence):
        return [
            event.copy()
            for event in self.recent
            if event["sequence"] > sequence
        ]

    def counts(self):
        return dict(sorted(self.totals.items()))

    def clear(self):
        self.recent.clear()
        self.totals.clear()

const PAGE_SIZE = 10;

export class Catalog {
  constructor(items = []) {
    this.items = new Map(items.map((item) => [item.id, { ...item }]));
  }

  add(item) {
    if (!item.id || this.items.has(item.id)) {
      throw new Error("id must be unique");
    }
    this.items.set(item.id, { ...item });
  }

  find(id) {
    const item = this.items.get(id);
    return item ? { ...item } : null;
  }

  remove(id) {
    return this.items.delete(id);
  }

  page(number = 1) {
    if (!Number.isInteger(number) || number < 1) {
      throw new Error("page number must be positive");
    }
    const sorted = [...this.items.values()].sort((a, b) =>
      a.id.localeCompare(b.id)
    );
    const offset = (number - 1) * PAGE_SIZE;
    return sorted.slice(offset, offset + PAGE_SIZE).map((item) => ({ ...item }));
  }

  get size() {
    return this.items.size;
  }
}
